export type ActivityScore = {
  correct: number;
  total: number;
};

export type ActivityResult = {
  completed: boolean;
  correct: boolean | null;
  score?: ActivityScore;
  attempts: number;
  responses: unknown;
  requiresReview?: boolean;
  status?: "correct" | "incorrect" | "review" | "recorded" | "error";
  itemResults?: ActivityItemResult[];
  checkNumber?: number;
  canRetry?: boolean;
  remainingAttempts?: number | null;
};

export type ActivityItemResult = {
  questionId: string;
  itemId?: string;
  correct: boolean | null;
  requiresReview?: boolean;
};

export type ActivityFeedbackCopy = {
  correct?: string;
  incorrect?: string;
};

export type ActivityOption = {
  id: string;
  label: string;
  description?: string;
  imageSrc?: string;
  imageAlt?: string;
};

export type ActivityItem = {
  id: string;
  label: string;
  text?: string;
  correctCategoryId?: string;
};

export type ActivityBlockContent = {
  presentation?: string;
  prompt?: string;
  instructions?: string;
  formative?: boolean;
  retry?: boolean;
  shuffle?: boolean;
  randomise?: boolean;
  maxAttempts?: number;
  feedback?: ActivityFeedbackCopy;
  marking?: { mode?: string };
  options?: ActivityOption[];
  correctOptionId?: string | null;
  items?: ActivityItem[];
  categories?: ActivityItem[];
  targets?: ActivityItem[];
  correct?: Record<string, string>;
  correctOrder?: string[];
  gaps?: Array<ActivityItem & { correctOptionId?: string }>;
  gapId?: string;
  questionId?: string;
  minChars?: number;
  minimumCharacters?: number;
  guidance?: string;
  placeholder?: string;
};

export type ActivityBlockDocument = {
  id: string;
  type: string;
  content?: ActivityBlockContent;
};

export type ActivityDocument = {
  id: string;
  version?: string;
  metadata?: { title?: string; summary?: string; status?: string };
  blocks?: ActivityBlockDocument[];
};

export function normaliseActivityType(value: string | undefined): string {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/\s+/g, "-");
}

export function isFormativeContent(content?: ActivityBlockContent): boolean {
  return content?.formative === true || content?.marking?.mode === "formative-local";
}

export function allowsRetry(content?: ActivityBlockContent): boolean {
  return content?.retry !== false;
}

export type ShuffleDecisionContext = {
  presentation?: string;
  options?: ActivityOption[];
};

/** True/False banks keep conventional True → False order for usability. */
export function looksLikeTrueFalseOptions(options?: ActivityOption[]): boolean {
  if (!options || options.length !== 2) return false;
  const labels = options
    .map((option) => String(option.label || "").trim().toLowerCase())
    .sort();
  return labels[0] === "false" && labels[1] === "true";
}

/**
 * Catalogue presentation shuffle policy:
 * - default ON for objective option/item banks (breaks authored first-correct bias)
 * - explicit shuffle/randomise false opts out
 * - true/false presentation (and conventional True/False labels) stay ordered
 */
export function shouldShuffle(
  content?: ActivityBlockContent,
  context?: ShuffleDecisionContext
): boolean {
  if (content?.shuffle === false || content?.randomise === false) return false;
  const presentation = normaliseActivityType(context?.presentation ?? content?.presentation);
  if (presentation === "true-false") return false;
  const options = context?.options ?? content?.options;
  if (looksLikeTrueFalseOptions(options)) return false;
  return true;
}

export const CATALOGUE_REACT_TYPES = [
  "single-choice",
  "option-cards",
  "classification",
  "drag-drop",
  "fill-gap",
  "phrase-completion",
  "ordering",
  "sequence",
  "short-response",
  "reflection"
] as const;

export const SHORT_RESPONSE_DEFAULT_MIN_CHARS = 200;
export const REFLECTION_DEFAULT_MIN_CHARS = 500;

export function resolveMinChars(
  content: Pick<ActivityBlockContent, "minChars" | "minimumCharacters"> | undefined,
  fallback: number
): number {
  const configured = Number(content?.minChars || content?.minimumCharacters || 0);
  return configured > 0 ? configured : fallback;
}

export function isCatalogueReactType(value: string | undefined): boolean {
  return (CATALOGUE_REACT_TYPES as readonly string[]).includes(normaliseActivityType(value));
}

export function questionIdFor(block: ActivityBlockDocument): string {
  return block.content?.questionId || block.id;
}
